void Restaurar_Fondo(int x, int y, int ancho, int alto) {
    for (int f = 0; f < alto; f++) {
        for (int c = 0; c < ancho; c++) {
            int mapX = x + c;
            int mapY = y + f;

            if (mapX >= 0 && mapX < COLUMNAS && mapY >= 0 && mapY < FILAS) {
                cursor(mapX, mapY);
                SetColorPorValor(laberinto[mapY][mapX]);                cout << "█";
            }
        }
    }
}

void Escribir_Texto(int x, int y, const char* texto, int colorTexto) {
    color(colorTexto);
    Console::SetCursorPosition(x, y);
    cout << texto;
}

