typedef struct Operacion {
    int a;
    int b;
    int respuesta;
    char signo;
} Operacion;

typedef struct MonstruoJuego {
    int x;
    int y;
    int tipo;
    Operacion operacion;
} MonstruoJuego;

int CarrilY(int indice) {
    int carriles[3] = { 14, 20, 26 };
    return carriles[indice];
}

Operacion Crear_Operacion(int nivel, int numero, bool habilidadActiva) {

    Operacion Operacion;
    if (nivel == 1) {
        // nivel 1 del 1 al 8
        Operacion.a = 1 + rand() % 8;
        Operacion.b = 1 + rand() % 8;
        Operacion.signo = '+';
        Operacion.respuesta = Operacion.a + Operacion.b;
    }
    else if (nivel == 2) {
        // nivel 2 del 1 al 12
        Operacion.a = 2 + rand() % 11; // 2 a 12
        Operacion.b = 1 + rand() % 9;  // 1 a 9
        if (habilidadActiva) {
            Operacion.signo = '+';
            Operacion.respuesta = Operacion.a + Operacion.b;
        }
        else {
            if (Operacion.b > Operacion.a) { int temp = Operacion.a; Operacion.a = Operacion.b; Operacion.b = temp; }
            Operacion.signo = '-';
            Operacion.respuesta = Operacion.a - Operacion.b;
        }
    }
    else {
        if (habilidadActiva) {

            Operacion.a = 10 + rand() % 21; // 10 a 30
            Operacion.b = 1 + rand() % 9;   // 1 a 9
            if (Operacion.b > Operacion.a) { int temp = Operacion.a; Operacion.a = Operacion.b; Operacion.b = temp; }
            Operacion.signo = '-';
            Operacion.respuesta = Operacion.a - Operacion.b;
        }
        else if (rand() % 2 == 0) {

            int raices[5] = { 4, 5, 6, 7, 8 };
            int indice = rand() % 5;
            Operacion.a = raices[indice] * raices[indice];
            Operacion.b = 0;
            Operacion.signo = 'r';
            Operacion.respuesta = raices[indice];
        }
        else {
            //multiplicacion
            Operacion.a = 2 + rand() % 6; // 2 a 7
            Operacion.b = 2 + rand() % 5; // 2 a 6
            Operacion.signo = 'x';
            Operacion.respuesta = Operacion.a * Operacion.b;
        }
    }
    return Operacion;
}

void Dibujar_Operacion(MonstruoJuego monstruo) {
    color(0);
    Console::SetCursorPosition(monstruo.x + 1, monstruo.y - 9);
    if (monstruo.operacion.signo == 'r') {
        cout << "raiz" << monstruo.operacion.a << " ";
    }
    else {
        cout << monstruo.operacion.a << monstruo.operacion.signo << monstruo.operacion.b << "   ";
    }
}

void Dibujar_Monstruo_Juego(MonstruoJuego monstruo) {
    if (monstruo.tipo == 1) Dibujar_Mounstro1(monstruo.x, monstruo.y);
    else if (monstruo.tipo == 2) Dibujar_Mounstro2(monstruo.x, monstruo.y);
    else Dibujar_Mounstro3(monstruo.x, monstruo.y);
    Dibujar_Operacion(monstruo);
}

