void Dibujar_Disparo(int desdeX, int hastaX, int y) {
    int inicio = desdeX + 10;
    if (inicio > hastaX) inicio = hastaX;
    color(0);
    for (int x = inicio; x < hastaX; x += 2) {
        Console::SetCursorPosition(x, y - 5);
        cout << "-";
        Sleep(4);
    }
    Restaurar_Fondo(inicio, y - 5, hastaX - inicio + 2, 1);
}

int Valor_Entrada(char entrada[], int largo) {
    int signo = 1;
    int valor = 0;
    int i = 0;
    if (largo > 0 && entrada[0] == '-') {
        signo = -1;
        i = 1;
    }
    for (; i < largo; i++) {
        valor = valor * 10 + (entrada[i] - '0');
    }
    return valor * signo;
}

bool Procesar_Tecla_Juego(int& carlX, int& carlY, char entrada[], int& largo, bool& enviar, bool& activarHabilidad, bool& usarHabilidad) {
    enviar = false;
    activarHabilidad = false;
    usarHabilidad = false;
    if (!_kbhit()) return false;

    char tecla = _getch();
    int salto_y = 6;
    int salto_x = 4;

    if (tecla == 'w' || tecla == 'W') {
        if (carlY - salto_y >= 14) {
            Restaurar_Fondo(carlX, carlY - 9, 11, 10);
            carlY -= salto_y;
            carlX += salto_x;
        }
        return true;
    }

    if (tecla == 's' || tecla == 'S') {
        if (carlY + salto_y <= 26) {
            Restaurar_Fondo(carlX, carlY - 9, 11, 10);
            carlY += salto_y;
            carlX -= salto_x;
        }
        return true;
    }

    if (tecla == 'e' || tecla == 'E') {
        activarHabilidad = true;
        return true;
    }

    if (tecla == ' ') {
        usarHabilidad = true;
        return true;
    }

    if (tecla >= '0' && tecla <= '9' && largo < 10) {
        entrada[largo] = tecla;
        largo++;
        entrada[largo] = '\0';
        return true;
    }

    if (tecla == '-' && largo == 0) {
        entrada[largo] = tecla;
        largo++;
        entrada[largo] = '\0';
        return true;
    }

    if (tecla == 8 && largo > 0) {
        largo--;
        entrada[largo] = '\0';
        return true;
    }

    if (tecla == 13 && largo > 0 && !(largo == 1 && entrada[0] == '-')) {
        enviar = true;
        return true;
    }



    return false;
}

