void Juego() {
    char nombreJugador[30];
    Pedir_Nombre_Jugador(nombreJugador);

    int vidas = configuracion.vidas;
    int totalPorNivel = configuracion.enemigosPorNivel;
    int carlX = 19, carlY = 20;
    char entrada[12] = "";
    int largoEntrada = 0;
    int tiempoRestante = configuracion.tiempoSegundos;
    int eliminadosTotales = 0;
    int puntaje = 0;
    const char* mensaje = "";

    salirJuego = false;

    for (int nivel = 1; nivel <= 3 && vidas > 0 && !salirJuego; nivel++) {
        int eliminados = 0;
        int tickMonstruo = 0;
        int contadorTiempo = 0;
        bool habilidadActiva = false;
        bool habilidadDisponible = false;
        int minimoHabilidad = totalPorNivel / 4;
        if (minimoHabilidad < 1) minimoHabilidad = 1;

        Cargar_Fondo_Nivel(nivel);
        carlX = 19;
        carlY = 20;
        Dibujar_Carl(carlX, carlY);

        MonstruoJuego monstruo;
        monstruo.x = 108;
        monstruo.y = CarrilY(nivel % 3);
        monstruo.tipo = nivel;
        monstruo.operacion = Crear_Operacion(nivel, eliminados, habilidadActiva);

        Dibujar_Monstruo_Juego(monstruo);
        Dibujar_HUD(nivel, vidas, eliminados, totalPorNivel, tiempoRestante, puntaje, habilidadActiva, entrada, mensaje);

        while (eliminados < totalPorNivel && vidas > 0 && tiempoRestante > 0 && !salirJuego) {
            bool enviar = false;
            bool activarHabilidad = false;
            bool usarHabilidad = false;

            if (Procesar_Tecla_Juego(carlX, carlY, entrada, largoEntrada, enviar, activarHabilidad, usarHabilidad)) {
                Dibujar_Carl(carlX, carlY);
                Dibujar_HUD(nivel, vidas, eliminados, totalPorNivel, tiempoRestante, puntaje, habilidadActiva, entrada, mensaje);
            }

            if (eliminados >= minimoHabilidad) habilidadDisponible = true;

            if (activarHabilidad) {
                if (habilidadDisponible && !habilidadActiva) {
                    habilidadActiva = true;
                    mensaje = "Habilidad activada";
                    monstruo.operacion = Crear_Operacion(nivel, eliminados, habilidadActiva);
                }
                else if (habilidadActiva) {
                    mensaje = "Habilidad ya activa";
                }
                else {
                    mensaje = "Elimina 25% primero";
                }
                Dibujar_HUD(nivel, vidas, eliminados, totalPorNivel, tiempoRestante, puntaje, habilidadActiva, entrada, mensaje);
            }

            if (usarHabilidad && nivel == 1 && habilidadActiva && carlY == monstruo.y) {
                Dibujar_Disparo(carlX, monstruo.x, monstruo.y);
                Restaurar_Fondo(monstruo.x, monstruo.y - 10, 9, 11);
                eliminados++;
                eliminadosTotales++;
                puntaje = eliminadosTotales * 100;
                mensaje = "Habilidad usada";

                if (eliminados < totalPorNivel) {
                    monstruo.x = 108;
                    monstruo.y = CarrilY((eliminados + nivel) % 3);
                    monstruo.tipo = nivel;
                    monstruo.operacion = Crear_Operacion(nivel, eliminados, habilidadActiva);
                    Dibujar_Monstruo_Juego(monstruo);
                }
                Dibujar_HUD(nivel, vidas, eliminados, totalPorNivel, tiempoRestante, puntaje, habilidadActiva, entrada, mensaje);
            }

            if (enviar) {
                int valor = Valor_Entrada(entrada, largoEntrada);
                entrada[0] = '\0';
                largoEntrada = 0;

                if (valor == monstruo.operacion.respuesta && carlY == monstruo.y) {
                    Dibujar_Disparo(carlX, monstruo.x, monstruo.y);
                    Restaurar_Fondo(monstruo.x, monstruo.y - 10, 9, 11);
                    eliminados++;
                    eliminadosTotales++;
                    puntaje = eliminadosTotales * 100;
                    mensaje = "Correcto";

                    if (eliminados < totalPorNivel) {
                        monstruo.x = 108;
                        monstruo.y = CarrilY((eliminados + nivel) % 3);
                        monstruo.tipo = nivel;
                        monstruo.operacion = Crear_Operacion(nivel, eliminados, habilidadActiva);
                        Dibujar_Monstruo_Juego(monstruo);
                    }
                }
                else {
                    vidas--;
                    mensaje = "Incorrecto";
                }
                Dibujar_HUD(nivel, vidas, eliminados, totalPorNivel, tiempoRestante, puntaje, habilidadActiva, entrada, mensaje);
            }

            tickMonstruo++;
            if (tickMonstruo >= 5) {
                Restaurar_Fondo(monstruo.x, monstruo.y - 10, 9, 11);
                monstruo.x--;

                if (monstruo.x <= 28) {
                    vidas--;
                    mensaje = "Perdiste una vida";
                    monstruo.x = 108;
                    monstruo.y = CarrilY((eliminados + nivel + vidas) % 3);
                    monstruo.tipo = nivel;
                    monstruo.operacion = Crear_Operacion(nivel, eliminados, habilidadActiva);
                }

                if (vidas > 0 && eliminados < totalPorNivel) Dibujar_Monstruo_Juego(monstruo);
                Dibujar_HUD(nivel, vidas, eliminados, totalPorNivel, tiempoRestante, puntaje, habilidadActiva, entrada, mensaje);
                tickMonstruo = 0;
            }

            contadorTiempo++;
            if (contadorTiempo >= 33) {
                for (int segundo = 0; segundo < 1; segundo++) {
                    tiempoRestante--;
                }
                contadorTiempo = 0;
                Dibujar_HUD(nivel, vidas, eliminados, totalPorNivel, tiempoRestante, puntaje, habilidadActiva, entrada, mensaje);
            }

            Dibujar_Carl(carlX, carlY);
            Sleep(30);
        }

        if (tiempoRestante <= 0) vidas = 0;

        if (vidas > 0 && nivel < 3 && !salirJuego) {
            Cargar_Fondo_Nivel(nivel + 1);
            Escribir_Texto(42, 13, "Nivel completado", 0);
            Escribir_Texto(36, 15, "Presiona una tecla para continuar", 0);
            system("pause>0");
        }
    }


    if (vidas > 0 && !salirJuego) {
        puntaje = puntaje + tiempoRestante * 100;
        Guardar_Puntaje(nombreJugador, puntaje);
        Pantalla_Ganar();

        Console::SetCursorPosition(91, 14); cout << "Puntaje final: " << puntaje;
    }
    else {
        Guardar_Puntaje(nombreJugador, puntaje);
        Pantalla_Perder();

        Console::SetCursorPosition(91, 14); cout << "Puntaje final: " << puntaje;
    }

    system("pause>0");
}

